<script setup lang="ts">
import { computed, ref } from "vue";
import {
  downloadBulkResourceErrorReport,
  downloadBulkCatalogTemplate,
  validateBulkCatalog, importBulkCatalog,
  downloadBulkCatalogErrorReport,
  downloadBulkResourceTemplate,
  importBulkResources,
  validateBulkResources,
} from "../api";
import type { BulkResourceValidation } from "../api/contracts";
import { useCatalogsStore } from "../stores/catalogs";
import Modal from "../components/Modal.vue";

type ImportKind = "resources" | "resourcesRoles" | "roles" | "profiles";
interface Card { kind: ImportKind; title: string; description: string; requirements: string; sheets: string[]; }
const cards: Card[] = [
  { kind: "resources", title: "Cargar recursos", description: "Registra endpoints HTTP sin modificar roles ni perfiles.", requirements: "Necesitas las aplicaciones y autorización para administrarlas.", sheets: ["Recursos", "Guía"] },
  { kind: "resourcesRoles", title: "Cargar recursos y roles", description: "Crea recursos y los vincula con roles en un solo archivo.", requirements: "Los roles y recursos de la relación se crean juntos.", sheets: ["Recursos", "Roles", "RolesxRecurso", "Guía"] },
  { kind: "roles", title: "Cargar roles", description: "Crea roles y, opcionalmente, sus permisos iniciales.", requirements: "Los recursos referenciados deben existir previamente.", sheets: ["Roles", "RolesxRecurso", "Guía"] },
  { kind: "profiles", title: "Cargar perfiles", description: "Crea perfiles y los asocia a roles existentes.", requirements: "Úsalo solo si esta aplicación administra perfiles.", sheets: ["Perfiles", "PerfilesxRol", "Guía"] },
];
const catalogs = useCatalogsStore();
const active = ref<ImportKind | null>(null), file = ref<File | null>(null), result = ref<BulkResourceValidation | null>(null), busy = ref(false), error = ref("");
const completed = ref<BulkResourceValidation | null>(null);
const modeOpen = ref(false);
const current = computed(() => cards.find(({ kind }) => kind === active.value));
const fileError = computed(() => file.value && (!/\.xlsx?$/i.test(file.value.name) || file.value.size > 5 * 1024 * 1024) ? "Selecciona un archivo .xlsx o .xls de máximo 5 MB." : "");
function save(blob: Blob, name: string) { const url = URL.createObjectURL(blob), link = document.createElement("a"); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url); }
function select(kind: ImportKind) { active.value = kind; file.value = null; result.value = null; error.value = ""; modeOpen.value = false; }
function removeFile() { file.value = null; result.value = null; error.value = ""; }
function finish() { completed.value = null; active.value = null; removeFile(); }
function choose(event: Event) { file.value = (event.target as HTMLInputElement).files?.[0] ?? null; result.value = null; error.value = ""; }
function unsupported() { error.value = "La validación y confirmación de esta modalidad aún no están disponibles."; }
async function template() { if (!active.value) return; busy.value = true; error.value = ""; try { const blob = active.value === "resources" ? await downloadBulkResourceTemplate("xlsx") : await downloadBulkCatalogTemplate(active.value); save(blob, `plantilla-${active.value}.xlsx`); } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible descargar la plantilla."; } finally { busy.value = false; } }
async function validate() { if (!file.value || fileError.value) return; if (active.value === "resourcesRoles") return unsupported(); busy.value = true; error.value = ""; try { result.value = active.value === "resources" ? (await validateBulkResources(file.value)).data : (await validateBulkCatalog(active.value!, file.value)).data; } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible validar el archivo."; } finally { busy.value = false; } }
async function report() { if (!file.value || active.value === "resourcesRoles") return; busy.value = true; try { const blob = active.value === "resources" ? await downloadBulkResourceErrorReport(file.value) : await downloadBulkCatalogErrorReport(active.value!, file.value); save(blob, "reporte-errores.xlsx"); } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible descargar el reporte."; } finally { busy.value = false; } }
async function confirm() { if (!file.value || !result.value?.ready || active.value === "resourcesRoles") return; busy.value = true; error.value = ""; try { const response = active.value === "resources" ? (await importBulkResources(file.value)).data : (await importBulkCatalog(active.value!, file.value)).data; result.value = response; if (response.ready) { completed.value = response; catalogs.notice = `Se procesaron ${response.validRows} filas.`; await catalogs.refresh(); } } catch (reason) { error.value = reason instanceof Error ? reason.message : "No fue posible confirmar la carga."; } finally { busy.value = false; } }
</script>

<template>
  <section class="bulk-page"><header class="module-heading"><div><p class="eyebrow">IMPORTACIÓN EXCEL</p><h1>Carga masiva</h1><p>Importa catálogos completos con una revisión antes de guardar.</p></div></header>
    <section class="mode-bar"><div class="mode-control"><label>¿Qué quieres cargar?</label><button class="mode-trigger" type="button" :aria-expanded="modeOpen" @click="modeOpen=!modeOpen"><span>{{ current?.title ?? 'Selecciona una modalidad' }}</span><b>⌄</b></button><div v-if="modeOpen" class="mode-options"><button v-for="card in cards" :key="card.kind" type="button" :class="{ selected: active===card.kind }" @click="select(card.kind)"><strong>{{ card.title }}</strong><small>{{ card.description }}</small></button></div></div><div v-if="current" class="mode-info"><b>{{ current.description }}</b><span>{{ current.requirements }}</span><span class="chips"><i v-for="sheet in current.sheets" :key="sheet">{{ sheet }}</i></span></div><button class="template-action" :disabled="!current || busy" @click="template"><span>↓</span> Descargar plantilla</button></section>
    <section v-if="current" class="import-flow"><ol class="progress"><li :class="{ active: true }"><b>1</b><span>Sube el Excel</span></li><li :class="{ active: !!file }"><b>2</b><span>Valida el contenido</span></li><li :class="{ active: !!result?.ready }"><b>3</b><span>Confirma la carga</span></li></ol>
      <section class="flow-step"><div><p class="eyebrow">PASO 1</p><h2>Selecciona el archivo</h2><p>Admite archivos <b>.xlsx</b> y <b>.xls</b>, de máximo 5 MB. Conserva los encabezados de la plantilla.</p></div><label class="dropzone" :class="{ uploaded:file, invalid:fileError }"><input type="file" accept=".xlsx,.xls" :disabled="busy" @change="choose"/><span class="upload-mark">↑</span><strong>{{ file ? file.name : 'Arrastra o selecciona el Excel' }}</strong><small>{{ file ? `${Math.ceil(file.size / 1024)} KB · listo para validar` : 'Haz clic para examinar tus archivos' }}</small><button v-if="file" class="remove-file" type="button" aria-label="Quitar archivo" @click.prevent="removeFile">×</button></label></section>
      <section class="flow-step"><div><p class="eyebrow">PASO 2</p><h2>Valida antes de guardar</h2><p>Comprobamos hojas, campos obligatorios, referencias, permisos y duplicados. Nada se guarda en esta etapa.</p></div><button class="create-action" :disabled="busy || !file || !!fileError" @click="validate">Validar archivo</button></section>
      <p v-if="fileError || error" class="import-error">{{ fileError || error }}</p>
      <section v-if="result" class="validation" :class="{ valid:result.ready }"><div><p class="eyebrow">RESULTADO DE VALIDACIÓN</p><h2>{{ result.ready ? 'Archivo listo para cargar' : 'Corrige los errores detectados' }}</h2><span>{{ result.totalRows }} filas · {{ result.validRows }} válidas · {{ result.invalidRows }} con errores</span></div><div class="confirm-actions"><button v-if="result.errors.length" class="panel-action" :disabled="busy" @click="report">Descargar reporte</button><button class="create-action" :disabled="busy || !result.ready" @click="confirm">Confirmar carga</button></div><div v-if="result.errors.length" class="errors"><table><thead><tr><th>Fila</th><th>Hoja / campo</th><th>Código</th><th>Descripción</th></tr></thead><tbody><tr v-for="issue in result.errors" :key="`${issue.row}-${issue.field}-${issue.code}`"><td>{{ issue.row || '—' }}</td><td>{{ issue.field }}</td><td>{{ issue.code }}</td><td>{{ issue.description }}</td></tr></tbody></table></div></section></section>
  </section><Modal v-if="completed" title="Carga completada" description="El lote fue guardado correctamente." submit-label="Cerrar" :error="''" :busy="false" eyebrow="IMPORTACIÓN EXITOSA" @close="finish" @submit="finish"><div class="completion"><b>{{ completed.validRows }}</b><span>filas cargadas sin errores</span></div></Modal>
</template>

<style scoped>
.mode-bar,.import-flow { border:1px solid var(--line); border-radius:10px; background:var(--paper); padding:22px; }.mode-bar { display:grid; grid-template-columns:minmax(255px,.8fr) 1.5fr auto; gap:18px; align-items:end; }.mode-control { position:relative; }.mode-bar label,.eyebrow { display:block; }.mode-bar label { font-size:12px; font-weight:600; margin-bottom:7px; }.mode-trigger { width:100%; height:42px; padding:0 12px; display:flex; align-items:center; justify-content:space-between; border:1px solid var(--line); border-radius:7px; background:var(--field); color:var(--ink); font-size:12px; text-align:left; }.mode-trigger:hover { border-color:var(--green); }.mode-trigger b { color:var(--green); font-size:18px; }.mode-options { position:absolute; z-index:5; top:calc(100% + 6px); width:100%; display:grid; overflow:hidden; border:1px solid var(--line); border-radius:8px; background:var(--paper); box-shadow:0 12px 28px rgba(17,19,18,.14); }.mode-options button { padding:10px 12px; display:grid; gap:3px; border:0; border-bottom:1px solid var(--soft-line); background:transparent; text-align:left; }.mode-options button:last-child { border:0; }.mode-options button:hover,.mode-options .selected { background:var(--green-tint); }.mode-options strong { font-size:12px; }.mode-options small { color:var(--text); font-size:10px; }.mode-info { display:grid; gap:5px; font-size:11px; color:var(--text); }.mode-info b { color:var(--ink); font-size:12px; }.chips { display:flex; gap:5px; flex-wrap:wrap; }.chips i { font-style:normal; padding:3px 6px; border-radius:4px; background:var(--green-wash); color:var(--green-ink); }.template-action { height:42px; padding:0 15px; border:0; border-radius:7px; background:var(--ink); color:#fff; font-size:12px; font-weight:600; white-space:nowrap; }.template-action:hover { background:var(--green-ink); }.template-action span { margin-right:6px; color:var(--green); font-size:17px; }.import-flow { margin-top:16px; display:grid; gap:16px; }.progress { display:flex; padding:0; margin:0; list-style:none; }.progress li { flex:1; display:flex; align-items:center; gap:7px; color:var(--faint); font-size:11px; }.progress b { display:grid; place-items:center; width:22px; height:22px; border-radius:50%; background:var(--field); }.progress .active { color:var(--green-ink); }.progress .active b { color:white; background:var(--green); }.flow-step,.validation { display:flex; align-items:center; justify-content:space-between; gap:20px; padding:18px; border:1px solid var(--soft-line); border-radius:8px; }.flow-step h2,.validation h2 { margin:4px 0; font-size:17px; }.flow-step p { margin:0; max-width:620px; color:var(--text); font-size:12px; line-height:1.5; }.dropzone { position:relative; min-width:270px; min-height:118px; box-sizing:border-box; padding:16px; display:grid; place-items:center; align-content:center; gap:5px; border:1.5px dashed rgba(17,19,18,.35); border-radius:8px; cursor:pointer; background:var(--field); text-align:center; }.dropzone:hover { border-color:var(--green); background:var(--green-tint); }.dropzone.uploaded { border-color:var(--green); background:var(--green-tint); }.dropzone.invalid { border-color:var(--red); }.dropzone input { position:absolute; opacity:0; width:1px; }.upload-mark { width:34px; height:34px; display:grid; place-items:center; border:1px solid var(--green); border-radius:7px; color:var(--green); font:500 23px 'IBM Plex Mono',monospace; }.dropzone strong { max-width:235px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:12px; }.dropzone small,.validation span { color:var(--text); font-size:11px; }.remove-file { position:absolute; top:7px; right:7px; width:23px; height:23px; padding:0; border:1px solid var(--line); border-radius:50%; background:var(--paper); color:var(--text); font-size:18px; line-height:18px; }.remove-file:hover { color:var(--red); border-color:var(--red); }.import-error { margin:0; color:var(--red); font-size:12px; }.validation { display:grid; grid-template-columns:1fr auto; background:rgba(185,61,60,.035); }.validation.valid { background:var(--green-tint); border-color:rgba(1,139,81,.35); }.confirm-actions { display:flex; gap:8px; }.errors { grid-column:1/-1; overflow:auto; max-height:220px; border:1px solid var(--soft-line); border-radius:6px; } table { width:100%; min-width:580px; border-collapse:collapse; font-size:11px; } th,td { text-align:left; padding:8px; border-bottom:1px solid var(--soft-line); } th { background:var(--field); font:500 9px 'IBM Plex Mono',monospace; color:var(--faint); }.completion { display:grid; place-items:center; padding:24px; gap:5px; }.completion b { font:500 44px 'IBM Plex Mono',monospace; color:var(--green); }.completion span { color:var(--text); } @media(max-width:720px){.mode-bar{grid-template-columns:1fr;align-items:stretch}.template-action,.flow-step .create-action,.dropzone,.confirm-actions button{width:100%}.flow-step,.validation{align-items:stretch;flex-direction:column}.validation{grid-template-columns:1fr}.confirm-actions{display:grid}.progress span{display:none}.progress li{justify-content:center}}
</style>
